import React from "react";
import  ReactDOM from "react-dom";
import './style.css';
import Header from "./components/header/header.jsx"
import Sidebar from "./components/sidebar/sidebar.jsx";
import Kategory from "./components/sidebar/kategory.jsx";
import Top from './components/content/top.jsx';
import { BrowserRouter, Route } from "react-router-dom";




 const App = ()=> {
     return  (
     <BrowserRouter>
     <div><Header/></div>
     <div><Top/></div>
      <div> <Sidebar /><Kategory></Kategory></div>



      </BrowserRouter>
     )
 }

ReactDOM.render(<Header></Header>, document.querySelector('#header'));
ReactDOM.render(<Sidebar></Sidebar>, document.querySelector('#sidebar'));
ReactDOM.render(<Top></Top>, document.querySelector('#top'));

export default App;
